            "phase": "APPROACH",
            "t": 0,
            "lx": None,
            "ly": None,
            "vx": 0.0,
            "vy": 0.0,
            "exit_hold_count": 0,
        }

    state = MEM.data["initial_state"]
    pd = sandbox.get_agent_position()
    dt = TIME_STEP

    if state["lx"] is not None:
        state["vx"] = (pd[0] - state["lx"]) / dt
        state["vy"] = (pd[1] - state["ly"]) / dt
    state["lx"], state["ly"] = pd[0], pd[1]
    x, y = pd[0], pd[1]
    vx, vy = state["vx"], state["vy"]

    front, up, down = sandbox.get_whisker_readings()
    w_comp = _weight_comp(sandbox)
    target_y = 1.5  # Mid-range to avoid floor and ceiling

    if state["phase"] == "APPROACH":
        # Push hard to break through initial wall at x=5.0
        if x < 5.0:
            fx = 100.0
        else:
            fx = 30.0 - 5.0 * vx

        # Maintain stable y-position to avoid floor/ceiling
        fy = 100.0 * (target_y - y) - 20.0 * vy + w_comp

        # Transition to unlock phase when in activation zone and moving slowly
        if ACTIVATION_X_MIN <= x <= ACTIVATION_X_MAX and abs(vx) < 0.75:
            state["phase"] = "UNLOCK"
            state["t"] = 0

    elif state["phase"] == "UNLOCK":
        vx_p, vy_p = sandbox.get_agent_velocity()
        spd = math.hypot(vx_p, vy_p)
        fx = BACKWARD_FX_THRESHOLD  # -35 N to satisfy unlock condition
        fy = 50.0 * (target_y - y) - 20.0 * vy + w_comp

        # Limit speed if too high
        if spd >= 0.99 * BACKWARD_SPEED_MAX:
            fx -= 1.5 * vx_p
            fy -= 1.5 * vy_p

        state["t"] += 1
        if state["t"] >= 60:
            state["phase"] = "ESCAPE"

    elif state["phase"] == "ESCAPE":
        # Use whiskers to avoid walls; apply strong forward force
        if front < 1.0:
            # Wall ahead: move up
            target_y = min(2.0, y + 0.1)
        elif down < 0.5:
            # Wall below: move up
            target_y = min(2.0, y + 0.1)
        elif up < 0.5:
            # Wall above: move down
            target_y = max(0.5, y - 0.1)

        fx = 50.0  # Aggressive forward force
        fy = 100.0 * (target_y - y) - 20.0 * vy + w_comp

        # If in exit zone, hold for 5 steps
        if x >= EXIT_X_MIN and 0.5 <= y <= 2.5:
            state["exit_hold_count"] += 1
            if state["exit_hold_count"] >= 5:
                # Task complete
                fx = 0.0
                fy = w_comp
        else:
            state["exit_hold_count"] = 0

    elif state["phase"] == "HOLD":
        fx = 0.0
        fy = w_comp

    sandbox.apply_agent_force(fx, fy)

